// Labels for autogenerated sidebar groups.
//
// Starlight labels a directory group with the directory's name and its
// `autogenerate` has no exclude option, so the "Using Brahma" group's
// `autogenerate: { directory: 'docs' }` turns docs/cli/ (the generated CLI
// reference) into a group named "cli", and docs/concepts/ into one named
// "concepts". A second `autogenerate: 'docs/cli'` group would list all of its
// pages twice and split the current-page marker and prev/next links between the
// copies. Instead, route middleware (src/route-data.mjs) renames the groups in
// place: the 154-page CLI reference is also collapsed (with its subgroups); the
// small directory groups keep Starlight's own collapsed state.

/**
 * URL prefix of a directory group's pages → { dir, label, collapse }.
 * `dir` is the directory name Starlight used as the label; `collapse` says
 * whether the group and its subgroups are forced closed.
 */
export const GROUP_LABELS = {
  '/docs/cli/': { dir: 'cli', label: 'CLI reference', collapse: true },
  '/docs/concepts/': { dir: 'concepts', label: 'Concepts', collapse: false },
  '/docs/safety/': { dir: 'safety', label: 'Safety', collapse: false },
  '/docs/guides/': { dir: 'guides', label: 'Guides', collapse: false },
  '/internals/decisions/': { dir: 'decisions', label: 'Decisions', collapse: false },
  '/internals/modules/': { dir: 'modules', label: 'Modules', collapse: false },
  '/internals/modules/brahmacore/': { dir: 'brahmacore', label: 'BrahmaCore', collapse: false },
};

function links(entry) {
  return entry.type === 'group' ? entry.entries.flatMap(links) : [entry];
}

function collapseAll(group) {
  group.collapsed = true;
  for (const entry of group.entries) if (entry.type === 'group') collapseAll(entry);
}

/**
 * Renames the groups named in `labels`, and collapses (with their subgroups)
 * those whose entry says `collapse`. A group matches when its label is the
 * directory name and every link in it is under the URL prefix. Subgroups are
 * visited too, so a labelled group nested in another (brahmacore/ inside
 * modules/) is renamed as well. Mutates `entries` (a route's own copy of the
 * sidebar).
 */
export function relabelGroups(entries, labels) {
  for (const entry of entries) {
    if (entry.type !== 'group') continue;
    const match = Object.entries(labels).find(([prefix, { dir }]) => {
      const hrefs = links(entry).map((l) => l.href);
      return entry.label === dir && hrefs.length > 0 && hrefs.every((h) => h.startsWith(prefix));
    });
    if (match) {
      entry.label = match[1].label;
      if (match[1].collapse) collapseAll(entry);
    }
    relabelGroups(entry.entries, labels);
  }
  return entries;
}
